{
  const args = process.argv.slice(2);

  // ✅ Нормализация путей для Windows
  const normalizedArgs = args.map(arg => {
    // Не трогаем опции (начинаются с -)
    if (arg.startsWith('-')) return arg;
    // Нормализуем пути
    return normalizePathForOS(arg);
  });

  const mode = normalizedArgs[0];

  let outputDir: string | undefined;
  let tsconfigPath: string | undefined;
  let includeEntities = false;
  let includeVueAnalysis = false;
  let includeBody = false;
  let fromFunction: string | undefined;
  let toFunction: string | undefined;
  const cleanArgs: string[] = [];

  // Извлекаем -o/--output и --tsconfig из аргументов
  for (let i = 0; i < normalizedArgs.length; i++) {
    const arg = normalizedArgs[i];
    if (arg === '-o' || arg === '--output') {
      if (arg && normalizedArgs[i + 1]) {
        outputDir = normalizedArgs[i + 1];
        i++; // пропускаем значение
      }
    } else if (arg === '--tsconfig') {
      if (normalizedArgs[i + 1]) {
        tsconfigPath = normalizedArgs[i + 1];
        i++;
      }
    } else if (arg === '--entities') {
      includeEntities = true;
    } else if (arg === '--vue-analysis' || arg === '--vue') {
      includeVueAnalysis = true;
    } else if (arg === '--include-body') {
      includeBody = true;
    } else if (arg === '--from') {
      if (normalizedArgs[i + 1]) {
        fromFunction = normalizedArgs[i + 1];
        i++;
      }
    } else if (arg === '--to') {
      if (normalizedArgs[i + 1]) {
        toFunction = normalizedArgs[i + 1];
        i++;
      }
    } else if (arg) {
      cleanArgs.push(arg);
    }
  }

  // Временно заменяем argv для существующего парсинга
  const originalArgv = [...process.argv];
  const newArgv = [originalArgv[0] || 'node', originalArgv[1] || 'cli.js', ...cleanArgs];
  process.argv = newArgv;

  if (!mode || mode === '--help' || mode === '-h') {
    showHelp();
    process.argv = originalArgv;
    return null;
  }

  // НОВЫЙ РЕЖИМ: hybrid-report - гибридный отчет (модули + функции)
  if (mode === 'hybrid-report' || mode === 'hybrid') {
    const targetPath = cleanArgs[1];
    const depth = cleanArgs[2] || '5';

    if (!targetPath) {
      console.error('❌ Укажите путь к файлу для гибридного отчета');
      process.argv = originalArgv;
      return null;
    }

    process.argv = originalArgv;
    return {
      mode: 'hybrid-report',
      targetPath,
      extraArg: depth,
      outputDir,
      tsconfigPath,
      includeEntities,
      includeVueAnalysis,
      includeBody,
      fromFunction,
      toFunction,
    };
  }

  // НОВЫЙ РЕЖИМ: semantic - семантический анализ
  if (mode === 'semantic') {
    const targetPaths = cleanArgs.slice(1);
    if (targetPaths.length === 0) {
      console.error('❌ Укажите пути к файлам или директориям для семантического анализа');
      process.argv = originalArgv;
      return null;
    }

    const options: any = {};

    for (let i = 2; i < cleanArgs.length; i++) {
      const arg = cleanArgs[i];
      const nextArg = cleanArgs[i + 1];

      switch (arg) {
        case '--recursive':
        case '-r':
          options.recursive = true;
          break;
        case '--formal':
        case '-f':
          options.formalVerification = true;
          break;
        case '--max-depth':
        case '-d':
          if (nextArg) {
            options.maxDepth = parseInt(nextArg, 10);
            i++;
          }
          break;
        case '--critical':
        case '-c':
          if (nextArg) {
            options.criticalFunctions = nextArg.split(',');
            i++;
          }
          break;
        case '--output':
        case '-o':
          if (nextArg) {
            options.outputDir = nextArg;
            i++;
          }
          break;
      }
    }

    process.argv = originalArgv;
    return {
      mode: 'semantic',
      targetPath: targetPaths[0] || '',
      extraArg: targetPaths.slice(1).join(','),
      options,
      outputDir,
      tsconfigPath,
      includeEntities,
      includeVueAnalysis,
      includeBody,
      fromFunction,
      toFunction,
    };
  }

  // НОВЫЙ РЕЖИМ: verify - формальная верификация функции
  if (mode === 'verify') {
    const targetFile = cleanArgs[1];
    if (!targetFile) {
      console.error('❌ Укажите путь к файлу для верификации');
      process.argv = originalArgv;
      return null;
    }

    const options: any = {};

    for (let i = 2; i < cleanArgs.length; i++) {
      const arg = cleanArgs[i];
      const nextArg = cleanArgs[i + 1];

      switch (arg) {
        case '--function':
        case '-f':
          if (nextArg) {
            options.functionName = nextArg;
            i++;
          }
          break;
        case '--contract':
        case '-c':
          if (nextArg) {
            options.contractPath = nextArg;
            i++;
          }
          break;
      }
    }

    process.argv = originalArgv;
    return {
      mode: 'verify',
      targetPath: targetFile,
      options,
      outputDir,
      tsconfigPath,
      includeEntities,
      includeVueAnalysis,
      includeBody,
      fromFunction,
      toFunction,
    };
  }

  // Режим: refactor - автоматический рефакторинг с выделением модулей
  if (mode === 'refactor') {
    const targetPath = cleanArgs[1];
    if (!targetPath) {
      console.error('❌ Укажите путь к файлу для рефакторинга');
      process.argv = originalArgv;
      return null;
    }

    const options: any = {};

    for (let i = 2; i < cleanArgs.length; i++) {
      const arg = cleanArgs[i];
      const nextArg = cleanArgs[i + 1];

      switch (arg) {
        case '--out-dir':
        case '-o':
          if (nextArg) {
            options.modulesDir = nextArg;
            i++;
          }
          break;
        case '--target-size':
        case '-t':
          if (nextArg) {
            options.targetClusterSize = parseInt(nextArg, 10);
            i++;
          }
          break;
        case '--max-size':
        case '-m':
          if (nextArg) {
            options.maxClusterSize = parseInt(nextArg, 10);
            i++;
          }
          break;
        case '--min-cohesion':
        case '-c':
          if (nextArg) {
            options.minCohesionScore = parseInt(nextArg, 10);
            i++;
          }
          break;
        case '--dry-run':
        case '-d':
          options.dryRun = true;
          break;
        case '--no-backup':
          options.createBackup = false;
          break;
        case '--no-vue':
          options.updateTemplate = false;
          break;
        case '--verbose':
        case '-v':
          options.verbose = true;
          break;
        case '--semantic':
        case '-s':
          options.semanticAnalysis = true;
          break;
      }
    }

    process.argv = originalArgv;
    return {
      mode: 'refactor',
      targetPath,
      options,
      outputDir,
      tsconfigPath,
      includeEntities,
      includeVueAnalysis,
      includeBody,
      fromFunction,
      toFunction,
    };
  }

  // Режим: analyze - анализ файла без изменений
  if (mode === 'analyze') {
    const targetPath = cleanArgs[1];
    if (!targetPath) {
      console.error('❌ Укажите путь к файлу для анализа');
      process.argv = originalArgv;
      return null;
    }

    const options: any = { dryRun: true };

    for (let i = 2; i < cleanArgs.length; i++) {
      const arg = cleanArgs[i];
      const nextArg = cleanArgs[i + 1];

      switch (arg) {
        case '--target-size':
        case '-t':
          if (nextArg) {
            options.targetClusterSize = parseInt(nextArg, 10);
            i++;
          }
          break;
        case '--max-size':
        case '-m':
          if (nextArg) {
            options.maxClusterSize = parseInt(nextArg, 10);
            i++;
          }
          break;
        case '--min-cohesion':
        case '-c':
          if (nextArg) {
            options.minCohesionScore = parseInt(nextArg, 10);
            i++;
          }
          break;
      }
    }

    process.argv = originalArgv;
    return {
      mode: 'analyze',
      targetPath,
      options,
      outputDir,
      tsconfigPath,
      includeEntities,
      includeVueAnalysis,
      includeBody,
      fromFunction,
      toFunction,
    };
  }

  // Mode: vue-analyze
  if (mode === 'vue-analyze' || mode === 'vue') {
    const targetPath = cleanArgs[1];
    if (!targetPath) {
      console.error('❌ Укажите путь к Vue файлу');
      process.argv = originalArgv;
      return null;
    }

    if (!targetPath.endsWith('.vue')) {
      console.error('❌ Файл должен иметь расширение .vue');
      process.argv = originalArgv;
      return null;
    }

    const options = {
      includeTemplateAST: true,
      includeScriptAST: true,
      extractComposableCalls: true,
    };

    for (let i = 2; i < cleanArgs.length; i++) {
      const arg = cleanArgs[i];
      switch (arg) {
        case '--no-template-ast':
          options.includeTemplateAST = false;
          break;
        case '--no-script-ast':
          options.includeScriptAST = false;
          break;
        case '--no-composables':
          options.extractComposableCalls = false;
          break;
      }
    }

    process.argv = originalArgv;
    return {
      mode: 'vue-analyze',
      targetPath,
      options: options as any,
      outputDir,
      tsconfigPath,
      includeEntities,
      includeVueAnalysis,
      includeBody,
      fromFunction,
      toFunction,
    };
  }

  // Mode: split-module
  if (mode === 'split-module' || mode === 'split') {
    const targetPath = cleanArgs[1];
    if (!targetPath) {
      console.error('❌ Укажите путь к файлу');
      process.argv = originalArgv;
      return null;
    }

    const options: SplitModuleOptions = {
      outputFile: 'ai-split-module-prompt.md',
      includeFullCode: true,
      includeMinified: true,
      includeGraph: true,
      includeStats: true,
      includeSuggestions: true,
      targetClusterSize: 3,
      maxClusterSize: 10,
      maxDepth: 5,
      excludePatterns: [...DEFAULT_EXCLUDE_PATTERNS],
      prefix: '',
    };

    for (let i = 2; i < cleanArgs.length; i++) {
      const arg = cleanArgs[i];
      const nextArg = cleanArgs[i + 1];

      switch (arg) {
        case '--output':
        case '-o':
          if (nextArg !== undefined) {
            options.outputFile = nextArg;
            i++;
          }
          break;
        case '--target-cluster-size':
        case '-t':
          if (nextArg !== undefined) {
            options.targetClusterSize = parseInt(nextArg, 10);
            i++;
          }
          break;
        case '--max-cluster-size':
        case '-m':
          if (nextArg !== undefined) {
            options.maxClusterSize = parseInt(nextArg, 10);
            i++;
          }
          break;
        case '--max-depth':
        case '-d':
          if (nextArg !== undefined) {
            options.maxDepth = parseInt(nextArg, 10);
            i++;
          }
          break;
        case '--exclude':
        case '-x':
          if (nextArg !== undefined) {
            options.excludePatterns = nextArg.split(',').map(e => e.trim());
            i++;
          }
          break;
        case '--prefix':
        case '-p':
          if (nextArg !== undefined) {
            options.prefix = nextArg;
            i++;
          }
          break;
        case '--no-full-code':
          options.includeFullCode = false;
          break;
        case '--no-minified':
          options.includeMinified = false;
          break;
        case '--no-graph':
          options.includeGraph = false;
          break;
        case '--no-stats':
          options.includeStats = false;
          break;
        case '--no-suggestions':
          options.includeSuggestions = false;
          break;
      }
    }

    process.argv = originalArgv;
    return {
      mode: 'split-module',
      targetPath,
      options,
      outputDir,
      tsconfigPath,
      includeEntities,
      includeVueAnalysis,
      includeBody,
      fromFunction,
      toFunction,
    };
  }

  // Mode: minify-folder
  if (mode === 'minify-folder') {
    const targetPath = cleanArgs[1];
    if (!targetPath) {
      console.error('❌ Укажите путь к каталогу');
      process.argv = originalArgv;
      return null;
    }

    const options: MinifyFolderOptions = {
      outputFile: 'ai-project-context.md',
      showStructure: true,
      addTableOfContents: true,
      sortByType: true,
      maxDepth: 10,
      extensions: ['.js', '.ts', '.tsx', '.jsx', '.vue', '.mjs', '.cjs'],
      excludePatterns: [...DEFAULT_EXCLUDE_PATTERNS],
    };

    for (let i = 2; i < cleanArgs.length; i++) {
      const arg = cleanArgs[i];
      const nextArg = cleanArgs[i + 1];

      switch (arg) {
        case '--output':
        case '-o':
          if (nextArg !== undefined) {
            options.outputFile = nextArg;
            i++;
          }
          break;
        case '--depth':
        case '-d':
          if (nextArg !== undefined) {
            options.maxDepth = parseInt(nextArg, 10);
            i++;
          }
          break;
        case '--extensions':
        case '-e':
          if (nextArg !== undefined) {
            options.extensions = nextArg.split(',').map(e => e.trim().toLowerCase());
            i++;
          }
          break;
        case '--exclude':
        case '-x':
          if (nextArg !== undefined) {
            options.excludePatterns = nextArg.split(',').map(e => e.trim());
            i++;
          }
          break;
        case '--no-structure':
          options.showStructure = false;
          break;
        case '--no-toc':
          options.addTableOfContents = false;
          break;
      }
    }

    process.argv = originalArgv;
    return {
      mode: 'minify-folder',
      targetPath,
      options,
      outputDir,
      tsconfigPath,
      includeEntities,
      includeVueAnalysis,
      includeBody,
      fromFunction,
      toFunction,
    };
  }

  // Mode: dead-code
  if (mode === 'dead-code') {
    const targetPath = cleanArgs[1];
    if (!targetPath) {
      console.error('❌ Укажите путь к файлу');
      process.argv = originalArgv;
      return null;
    }
    process.argv = originalArgv;
    return {
      mode: 'dead-code',
      targetPath,
      extraArg: '',
      depthArg: '',
      outputDir,
      tsconfigPath,
      includeEntities,
      includeVueAnalysis,
      includeBody,
      fromFunction,
      toFunction,
    };
