        endLine: node.loc?.end?.line || 1,
        body: bodyText,
        isMethod: false,
        className: undefined,
        isNested,
        parentFunction: parentFunc,
        isArrow: true,
        isEventHandler: isEventHandlerNode,
        eventType,
        depth: depth,
        complexity: calculateComplexity(node),
        security: analyzeSecurity(bodyText || ''),
