            if (p.type === 'AssignmentPattern' && p.left) return p.left.name || 'unknown';
            return 'unknown';
          })
          : [];

        const parentFunc = className;
        const bodyText = node.value?.body ? extractBodyText(node.value.body) : undefined;

        const funcInfo: FunctionInfo = {
