          line: node.loc?.start?.line || 1,
          isAsync: node.value?.async || false,
          isExported,
          params,
          returnType: node.value?.returnType?.typeName?.name || undefined,
          calls: [],
          calledBy: [],
          startLine: node.loc?.start?.line || 1,
          endLine: node.loc?.end?.line || 1,
