        if (currentCalls && !currentCalls.includes(calledFunction)) {
          currentCalls.push(calledFunction);
        }
      }
    },
    leave(node: any) {
      if ((node.type === 'FunctionDeclaration' || node.type === 'FunctionExpression') && node.id) {
        currentFunction = null;
        currentDepth = 0;
