      break;
    case '<=':
      normalizedOp = 'lte';
      break;
    case '>':
      normalizedOp = 'gt';
      break;
    case '>=':
      normalizedOp = 'gte';
      break;
    default:
      normalizedOp = operator;
  }

  // Используем нормализованный оператор
  switch (normalizedOp) {
    case 'eq':
      return { type: 'equality', left, right };
    case 'neq':
      return { type: 'inequality', left, right };
    case 'gt':
      return {
        type: 'range',
        variable: left,
        min: typeof right === 'number' ? right + 1 : 0,
        max: Number.MAX_SAFE_INTEGER,
      };
    case 'gte':
      return {
        type: 'range',
        variable: left,
        min: typeof right === 'number' ? right : 0,
        max: Number.MAX_SAFE_INTEGER,
      };
    case 'lt':
      return {
        type: 'range',
        variable: left,
        min: -Number.MAX_SAFE_INTEGER,
        max: typeof right === 'number' ? right - 1 : 0,
      };
    case 'lte':
      return {
        type: 'range',
        variable: left,
        min: -Number.MAX_SAFE_INTEGER,
        max: typeof right === 'number' ? right : 0,
      };
    default:
