      implements: ensureArray(cls.implements).map((i: any) => safeString(i)),
      startLine: safeNumber(cls.startLine || cls.line),
      endLine: safeNumber(cls.endLine || cls.line),
      body: '',
      vscode: '',
    };

    nodes.push({
      id: nodeId,
      name: className,
