                <button onclick="toggleLabels()">🏷️ Метки</button>
                <button onclick="toggleCycles()">🔄 Циклы</button>
            </div>
        </div>

        ${
          report.cycles.length > 0
            ? `
        <div class="cycles-section">
            <h2>🔄 Циклические зависимости (${report.cycles.length})</h2>
