                `
                    : '<div style="color:#64748b; font-size:12px; margin-top:8px;">Нет функций</div>'
                }
            </div>
            `
              )
              .join('')}
        </div>
    </div>

    <script>
        const graphData = ${jsonData};
        let currentZoom = 1;
        let showLabels = true;
        let showCycles = true;
        let svg, g, zoom;
        let currentView = 'd3';

        window.switchView = function(view) {
            currentView = view;
            document.getElementById('d3-graph').style.display = view === 'd3' ? 'block' : 'none';
            document.getElementById('svg-graph').style.display = view === 'svg' ? 'block' : 'none';
            document.getElementById('list-view').style.display = view === 'list' ? 'block' : 'none';

            document.querySelectorAll('.view-toggle button').forEach(b => b.classList.remove('active'));
            document.querySelectorAll('.view-toggle button').forEach(b => {
                if ((view === 'd3' && b.textContent.includes('D3')) ||
                    (view === 'svg' && b.textContent.includes('SVG')) ||
                    (view === 'list' && b.textContent.includes('Список'))) {
                    b.classList.add('active');
                }
            });

            if (view === 'd3' && !document.querySelector('#d3-graph svg')) {
                initGraph();
            }
        };

        function initGraph() {
            const width = document.getElementById('d3-graph').clientWidth || 900;
            const height = 700;

            const container = d3.select('#d3-graph');
            container.html('');

            svg = container.append('svg')
                .attr('width', width)
                .attr('height', height)
                .style('background', '#0f172a')
                .style('border-radius', '8px');

            const levelColors = ['#4ade80', '#60a5fa', '#a78bfa', '#f472b6', '#fbbf24', '#f87171', '#22d3ee'];

            const nodes: any[] = [];
            const edges: any[] = [];
            const nodeIds = new Set<string>();

            graphData.modules.forEach((module: HybridModule) => {
                const id = module.path;
                if (!nodeIds.has(id)) {
                    nodeIds.add(id);
                    const isRoot = module.path === graphData.root;
                    nodes.push({
                        id: id,
                        name: isRoot ? '⭐ ' + module.name : module.name,
                        type: module.type,
                        level: module.level,
                        isRoot: isRoot,
                        functions: module.functions.length,
                        exports: module.exports.length,
                        imports: module.imports.length,
                        color: levelColors[module.level % levelColors.length] || '#94a3b8',
                        size: isRoot ? 35 : 25,
                    });
                }

                module.functions.forEach((func: HybridFunction) => {
                    const funcId = id + '#func:' + func.name;
                    if (!nodeIds.has(funcId)) {
                        nodeIds.add(funcId);
                        nodes.push({
                            id: funcId,
                            name: func.isExported ? '📤 ' + func.name : func.name,
                            type: 'function',
                            level: module.level,
                            isRoot: false,
                            isExported: func.isExported,
                            isAsync: func.isAsync,
                            calls: func.calls,
                            parent: id,
                            color: func.isExported ? '#f87171' : '#fbbf24',
                            size: 8,
                        });
                    }
                });
            });

            graphData.graph.edges.forEach((edge: { from: string; to: string; type: string; level?: number }) => {
                const fromLevel = graphData.levels[edge.from] || 0;
                const toLevel = graphData.levels[edge.to] || 0;
                edges.push({
                    source: edge.from,
                    target: edge.to,
                    type: edge.type,
                    level: edge.level,
                    fromLevel: fromLevel,
                    toLevel: toLevel,
                    isCycle: fromLevel > toLevel,
                });
            });

            graphData.modules.forEach((module: HybridModule) => {
                module.functions.forEach((func: HybridFunction) => {
                    func.calls.forEach((call: string) => {
                        const targetFunc = module.functions.find((f: HybridFunction) => f.name === call);
                        if (targetFunc) {
                            edges.push({
                                source: module.path + '#func:' + func.name,
                                target: module.path + '#func:' + targetFunc.name,
                                type: 'call',
                                isCall: true,
                            });
                        }
                    });
                });
            });

            zoom = d3.zoom()
                .extent([[0, 0], [width, height]])
                .scaleExtent([0.1, 4])
                .on('zoom', (event: any) => {
                    g.attr('transform', event.transform);
                    currentZoom = event.transform.k;
                });

            svg.call(zoom);

            g = svg.append('g');

            const simulation = d3.forceSimulation(nodes)
                .force('link', d3.forceLink(edges).id((d: any) => d.id).distance(150))
                .force('charge', d3.forceManyBody().strength(-300))
                .force('center', d3.forceCenter(width / 2, height / 2))
                .force('collision', d3.forceCollide().radius(30))
                .force('x', d3.forceX(width / 2).strength(0.05))
                .force('y', d3.forceY(height / 2).strength(0.05));

            const link = g.append('g')
                .selectAll('line')
                .data(edges)
                .enter()
                .append('line')
                .attr('stroke', (d: any) => d.isCall ? '#ef4444' : (d.isCycle ? '#f59e0b' : '#3b82f6'))
                .attr('stroke-width', (d: any) => d.isCall ? 1.5 : (d.isCycle ? 2 : 1))
                .attr('stroke-opacity', (d: any) => d.isCall ? 0.8 : 0.5)
                .attr('stroke-dasharray', (d: any) => d.isCall ? 'none' : (d.isCycle ? '8,4' : 'none'))
                .attr('class', (d: any) => d.isCycle ? 'cycle-edge' : '');

            const node = g.append('g')
                .selectAll('circle')
                .data(nodes)
                .enter()
                .append('circle')
                .attr('r', (d: any) => d.size || 10)
                .attr('fill', (d: any) => d.color)
                .attr('stroke', (d: any) => d.isRoot ? '#fbbf24' : '#1e293b')
                .attr('stroke-width', (d: any) => d.isRoot ? 3 : 1)
                .call(d3.drag()
                    .on('start', dragstarted)
                    .on('drag', dragged)
                    .on('end', dragended));

            const label = g.append('g')
                .selectAll('text')
                .data(nodes)
                .enter()
                .append('text')
                .text((d: any) => d.name)
                .attr('font-size', (d: any) => d.type === 'function' ? '8px' : '11px')
                .attr('fill', '#e2e8f0')
                .attr('text-anchor', 'middle')
                .attr('dy', (d: any) => d.type === 'function' ? -14 : 35)
                .style('font-family', 'monospace')
                .style('pointer-events', 'none');

            const info = g.append('g')
                .selectAll('text.info')
                .data(nodes.filter((d: any) => d.type !== 'function'))
                .enter()
                .append('text')
                .text((d: any) => d.functions + ' функций')
                .attr('font-size', '7px')
                .attr('fill', '#94a3b8')
                .attr('text-anchor', 'middle')
                .attr('dy', 48)
                .style('pointer-events', 'none');

            function ticked() {
                link
                    .attr('x1', (d: any) => d.source.x)
                    .attr('y1', (d: any) => d.source.y)
                    .attr('x2', (d: any) => d.target.x)
                    .attr('y2', (d: any) => d.target.y);

                node
                    .attr('cx', (d: any) => d.x)
                    .attr('cy', (d: any) => d.y);

                label
                    .attr('x', (d: any) => d.x)
                    .attr('y', (d: any) => d.y);

                info
                    .attr('x', (d: any) => d.x)
                    .attr('y', (d: any) => d.y);
            }

            simulation.on('tick', ticked);

            function dragstarted(event: any, d: any) {
                if (!event.active) simulation.alphaTarget(0.3).restart();
                d.fx = d.x;
                d.fy = d.y;
            }

            function dragged(event: any, d: any) {
                d.fx = event.x;
                d.fy = event.y;
            }

            function dragended(event: any, d: any) {
                if (!event.active) simulation.alphaTarget(0);
                d.fx = null;
                d.fy = null;
            }

            window.zoomIn = function() {
                zoom.scaleBy(svg.transition().duration(300), 1.3);
            };

            window.zoomOut = function() {
                zoom.scaleBy(svg.transition().duration(300), 0.7);
            };

            window.resetZoom = function() {
                svg.transition().duration(500).call(zoom.transform, d3.zoomIdentity);
            };

            window.toggleLabels = function() {
                showLabels = !showLabels;
                label.style('display', showLabels ? 'block' : 'none');
                info.style('display', showLabels ? 'block' : 'none');
            };

            window.toggleCycles = function() {
                showCycles = !showCycles;
                document.querySelectorAll('.cycle-edge').forEach((el: Element) => {
                    (el as HTMLElement).style.display = showCycles ? 'block' : 'none';
                });
                const cyclesSection = document.querySelector('.cycles-section');
                if (cyclesSection) {
                    (cyclesSection as HTMLElement).style.display = showCycles ? 'block' : 'none';
                }
            };
        }

        window.addEventListener('load', function() {
            initGraph();
            const svgGraph = document.getElementById('svg-graph');
            if (svgGraph) {
                const svgEl = svgGraph.querySelector('svg');
                if (svgEl) {
                    svgPanZoom(svgEl, {
                        zoomEnabled: true,
                        controlIconsEnabled: true,
                        fit: true,
                        center: true,
                        minZoom: 0.1,
                        maxZoom: 4,
                    });
                }
            }
        });

        window.addEventListener('resize', function() {
            const container = document.getElementById('d3-graph');
            if (container && currentView === 'd3') {
                const width = container.clientWidth || 900;
                const svgEl = container.querySelector('svg');
                if (svgEl) {
                    svgEl.setAttribute('width', width);
                }
            }
        });
    </script>
</body>
</html>`;
}

{
  let md = '# 🔀 ГИБРИДНЫЙ ОТЧЕТ: МОДУЛИ + ФУНКЦИИ\n\n';

  md += `**Точка входа:** \`${report.root}\`\n`;
  md += `**Дата:** ${new Date().toLocaleString()}\n\n`;

  // ============================================
  // СТАТИСТИКА
  // ============================================
  md += '## 📊 СТАТИСТИКА\n\n';
  md += '| Показатель | Значение |\n';
  md += '|------------|----------|\n';
  md += `| Модулей | ${report.stats.totalModules} |\n`;
  md += `| Функций | ${report.stats.totalFunctions} |\n`;
  md += `| Экспортов | ${report.stats.totalExports} |\n`;
  md += `| Импортов | ${report.stats.totalImports} |\n`;
  md += `| Компонентов | ${report.stats.totalComponents} |\n`;
  md += `| Композаблов | ${report.stats.totalComposables} |\n`;
  md += `| Циклов | ${report.stats.cycles} |\n`;
  md += `| Глубина | ${report.stats.maxDepth} |\n\n`;

  // ============================================
  // СТАТИСТИКА ПО УРОВНЯМ
  // ============================================
  md += '### По уровням\n\n';
  md += '| Уровень | Модулей | Функций |\n';
  md += '|---------|---------|---------|\n';

  const sortedLevels = Object.entries(report.stats.byLevel).sort(
    (a, b) => parseInt(a[0]) - parseInt(b[0])
  );

  for (const [level, data] of sortedLevels) {
    md += `| ${level} | ${data.modules} | ${data.functions} |\n`;
  }
  md += '\n';

  // ============================================
  // МОДУЛИ
  // ============================================
  md += '## 📁 МОДУЛИ\n\n';

  // Сортируем модули по уровню
  const sortedModules = [...report.modules].sort((a, b) => a.level - b.level);

  for (const module of sortedModules) {
    const isRoot = module.path === report.root;
    md += `### ${isRoot ? '⭐ ' : ''}${module.name}\n`;
    md += `**Путь:** \`${module.path}\`\n`;
    md += `**Тип:** ${module.type}\n`;
    md += `**Уровень:** ${module.level}\n\n`;

    // Экспорты
    if (module.exports.length > 0) {
      md += '**Экспорты:**\n';
      for (const exp of module.exports) {
        md += `- \`${exp}\`\n`;
      }
      md += '\n';
    }

    // Импорты
    if (module.imports.length > 0) {
      md += '**Импорты:**\n';
      for (const imp of module.imports) {
        md += `- \`${imp}\`\n`;
      }
      md += '\n';
    }

    // Функции
    if (module.functions.length > 0) {
      md += '**Функции:**\n';

      // Сортируем функции: сначала экспортированные, затем внутренние
      const sortedFunctions = [...module.functions].sort((a, b) => {
        if (a.isExported && !b.isExported) return -1;
        if (!a.isExported && b.isExported) return 1;
        return a.name.localeCompare(b.name);
      });

      for (const func of sortedFunctions) {
        const exported = func.isExported ? ' 📤' : '';
        const async = func.isAsync ? ' ⚡' : '';
        const calls = func.calls.length > 0 ? ` → ${func.calls.join(', ')}` : '';
        const source =
          func.exportSource === 'self'
            ? ' (self)'
            : func.exportSource === 'external'
              ? ` (from ${func.exportModule})`
              : ' (re-export)';

        md += `- \`${func.name}\`${exported}${async}${calls}${source}\n`;
        md += `  - Строки: ${func.startLine}-${func.endLine}\n`;
        md += `  - Параметры: ${func.params.length > 0 ? func.params.join(', ') : 'нет'}\n`;

        if (func.body && func.body.length > 0) {
          const bodyPreview =
            func.body.length > 100 ? func.body.substring(0, 100) + '...' : func.body;
          md += `  - Тело: \`${bodyPreview}\`\n`;
        }
      }
      md += '\n';
    }

    // Компоненты (Vue/React)
    if (module.components.length > 0) {
      md += '**Компоненты:**\n';
      for (const comp of module.components) {
        md += `- \`${comp}\`\n`;
      }
      md += '\n';
    }

    // Композаблы (Vue composables)
    if (module.composables.length > 0) {
      md += '**Композаблы:**\n';
      for (const comp of module.composables) {
        md += `- \`${comp}\`\n`;
      }
      md += '\n';
    }

    md += '---\n\n';
  }

  // ============================================
  // ЦИКЛИЧЕСКИЕ ЗАВИСИМОСТИ
  // ============================================
  if (report.cycles.length > 0) {
    md += '## 🔄 ЦИКЛИЧЕСКИЕ ЗАВИСИМОСТИ\n\n';
    md += `Обнаружено **${report.cycles.length}** циклических зависимостей:\n\n`;

    for (const cycle of report.cycles) {
      md += `- ${cycle.join(' → ')}\n`;
    }
    md += '\n';

    md += '### ⚠️ Рекомендации по устранению циклов\n\n';
    md += '1. **Выделите общий код** в отдельный модуль\n';
    md += '2. **Используйте Dependency Injection** вместо прямых зависимостей\n';
    md += '3. **Внедрите интерфейсы** для разрыва жестких связей\n';
    md += '4. **Пересмотрите архитектуру** - возможно, модули должны быть на одном уровне\n';
  }

  // ============================================
  // ВЕРСИЯ И ПОДПИСЬ
  // ============================================
  md += '---\n\n';
  md += `*Сгенерировано AST Analyzer Hybrid Report v3.0.0*\n`;
  md += `*Время генерации: ${new Date().toLocaleString()}*\n`;

  return md;
}

