      try {
        const files = fs.readdirSync(dir);
        for (const file of files) {
          const fullPath = path.join(dir, file);
          if (fs.statSync(fullPath).isDirectory()) {
            const result = walkDir(fullPath);
            if (result) return result;
          } else if (file === fileName) {
            return fullPath;
          }
        }
      } catch (error: any) {
        // Игнорируем ошибки
