  if (executionSteps.some(s => s.branches?.isCyclic)) {
    flowType = 'conditional';
  }

  return {
    entryPoint: rootKey,
    direction: 'top-down',
    entryFunctions,
    executionFlow: {
      type: flowType,
      steps: executionSteps,
    },
  };
