      'v-for': /v-for/g,
      'v-on': /v-on/g,
      'v-model': /v-model/g,
      'v-bind': /v-bind/g,
      'v-show': /v-show/g,
      'v-else': /v-else/g,
      'v-else-if': /v-else-if/g,
